package org.diy.liferecorder;

import android.content.Intent;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

/** A date-scoped reading surface; background work never blocks navigation. */
public final class HourlySummaryActivity extends AppScreen {
    private final java.util.concurrent.ExecutorService loader=java.util.concurrent.Executors.newSingleThreadExecutor();private long day;private int generation;private LinearLayout list;private TextView state;private final Handler refresh=new Handler();private boolean loading;private String signature="";
    public void onCreate(Bundle saved){super.onCreate(saved);day=saved==null?getIntent().getLongExtra("day",System.currentTimeMillis()):saved.getLong("day");String job=getIntent().getStringExtra("job_id");if(saved==null&&job!=null)try{JSONArray rows=store.rows("SELECT start FROM hourly_summaries WHERE job_id=?",job);if(rows.length()>0)day=rows.getJSONObject(0).getLong("start");}catch(Exception ignored){}render();}
    public void onSaveInstanceState(Bundle saved){saved.putLong("day",day);super.onSaveInstanceState(saved);}
    private void render(){generation++;signature="";frame("逐小时总结");button(body,"‹ 返回",this::finish);body.addView(title("逐小时总结",25));body.addView(text("每小时自动整理，点击引用回听原声。",14,MUTED));
        LinearLayout date=row();body.addView(date);Button previous=button(date,"‹",()->shift(-1));dateArrow(previous,"前一天");TextView dateText=title(new java.text.SimpleDateFormat("M月d日",Locale.CHINA).format(new Date(day)),17);dateText.setGravity(Gravity.CENTER);dateText.setMinHeight(dp(48));date.addView(dateText,new LinearLayout.LayoutParams(0,-2,1));Button next=button(date,"›",()->shift(1));dateArrow(next,"后一天");dateText.setOnClickListener(v->{Calendar c=Calendar.getInstance();c.setTimeInMillis(day);new PebbleDatePickerDialog(this,(d,y,m,n)->{Calendar chosen=Calendar.getInstance();chosen.set(y,m,n,0,0,0);chosen.set(Calendar.MILLISECOND,0);day=chosen.getTimeInMillis();render();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});
        LinearLayout controls=row();controls.setGravity(Gravity.CENTER_VERTICAL);controls.setPadding(dp(12),0,dp(8),0);controls.setBackground(bg(TINT,12));state=text("",13,SAGE);controls.addView(state,new LinearLayout.LayoutParams(0,-2,1));Button options=button(controls,"设置",this::manage);options.setCompoundDrawables(null,null,null,null);options.setCompoundDrawablePadding(0);options.setPadding(dp(4),0,dp(4),0);options.setSingleLine(true);options.setMinWidth(0);options.setMinimumWidth(0);options.setLayoutParams(new LinearLayout.LayoutParams(dp(64),dp(48)));body.addView(controls);
        body.addView(text("手机本地时间 · "+ZoneId.systemDefault().getId(),11,MUTED));
        list=column();body.addView(list);body.addView(text("小时结束后整理；新转写或校对会更新对应小时。离线、省电时延后。跨整点的句子按开始时间归档。",12,MUTED));load();
    }
    private void dateArrow(Button button,String description){button.setContentDescription(description);button.setMinWidth(0);button.setMinimumWidth(0);button.setPadding(0,0,0,0);button.setLayoutParams(new LinearLayout.LayoutParams(dp(48),dp(48)));}
    private void manage(){new LocalDialog(this).setTitle("逐小时总结设置").setItems(new String[]{HourlyAutomation.enabled(this)?"关闭自动逐小时总结":"开启自动逐小时总结","配置分析 API","自动整理说明"},(d,n)->{if(n==0)HourlyAutomation.toggle(this,this::render);else if(n==1)startActivity(new Intent(this,MainActivity.class).putExtra("page","settings").putExtra("setting","llm"));else message("自动逐小时总结","小时结束后自动整理已有逐句转写，也会补齐历史时段。新转写或校对只更新受影响的小时。没有原文的时段不生成内容。\n\n网络或系统省电可能延后处理；失败或中断后可手动重试。关闭自动总结后，已生成内容仍保留。");}).show();}

    private void shift(int days){Calendar c=Calendar.getInstance();c.setTimeInMillis(day);c.add(Calendar.DATE,days);day=c.getTimeInMillis();render();}
    private void load(){if(loading)return;loading=true;final int token=generation;final long selected=day;loader.execute(()->{try(RecordStore db=new RecordStore(this)){
        JSONArray hours=HourlySummaries.day(db,selected,ZoneId.systemDefault());long now=System.currentTimeMillis();for(int i=0;i<hours.length();i++){JSONObject h=hours.getJSONObject(i);JSONObject evidence=HourlySummaries.snapshot(db,h.getLong("start"),h.getLong("end"),h.getString("zone"));if(!h.optString("result").isEmpty()&&!AudioReview.object(h.optString("evidence")).optString("hash").equals(evidence.optString("hash"))){h.put("result","");h.put("job_status","");}h.put("display_evidence",evidence);h.put("display_state",HourlySummaries.state(h,evidence,now,HourlyAutomation.enabled(this)));}
        String next=hours.toString()+HourlyAutomation.enabled(this);runOnUiThread(()->{loading=false;if(isDestroyed()||token!=generation){if(!isDestroyed())load();return;}state.setText(HourlyAutomation.enabled(this)?"自动总结已开启":"自动总结未开启");if(next.equals(signature))return;signature=next;int y=scroll.getScrollY();list.removeAllViews();try{int shown=0;for(int i=0;i<hours.length();i++){JSONObject h=hours.getJSONObject(i);if(h.getJSONObject("display_evidence").optInt("recordings")==0)continue;showHour(h);shown++;}if(shown==0){LinearLayout empty=card(list);empty.addView(title("这一天还没有录音",18));empty.addView(text("同步录音并完成逐句转写后，会在这里自动整理。空白时段不会补写内容。",14,MUTED));}}catch(Exception e){notice.setText("总结读取失败，请重新打开页面");}scroll.post(()->scroll.scrollTo(0,y));});
    }catch(Exception e){runOnUiThread(()->{loading=false;if(!isDestroyed()&&token==generation)notice.setText("暂时无法读取逐小时总结");});}});}
    private void showHour(JSONObject hour)throws Exception {
        JSONObject evidence=hour.getJSONObject("display_evidence");LinearLayout c=card(list);c.addView(title(HourlySummaries.label(hour),20));c.addView(text(hour.getString("display_state"),12,SAGE));c.addView(text(DayOverview.duration(evidence.optLong("recorded_ms"))+" 已同步 · "+evidence.optInt("recordings")+" 段录音"+(evidence.optInt("pending")>0?" · "+evidence.optInt("pending")+" 段待转写":"")+(evidence.optInt("unaligned")>0?" · "+evidence.optInt("unaligned")+" 段未对齐":""),12,MUTED));
        if(!hour.optString("result").isEmpty()){
            JSONObject result=new JSONObject(hour.getString("result"));JSONArray claims=result.getJSONArray("claims");LinearLayout more=column();int preview=Math.min(3,claims.length());for(int i=0;i<claims.length();i++)showClaim(i<preview?c:more,claims.getJSONObject(i));if(claims.length()>preview){more.setVisibility(View.GONE);c.addView(more);Button expand=button(c,"展开其余 "+(claims.length()-preview)+" 条",()->more.setVisibility(more.getVisibility()==View.GONE?View.VISIBLE:View.GONE));expand.setOnClickListener(v->{boolean show=more.getVisibility()==View.GONE;more.setVisibility(show?View.VISIBLE:View.GONE);expand.setText(show?"收起更多内容":"展开其余 "+(claims.length()-preview)+" 条");});}
            if(claims.length()==0)c.addView(text("这小时的转写没有足够内容形成总结，可查看原文。",14,MUTED));c.addView(text("AI 整理 · 点击引用核对原文",11,MUTED));
        }
        String status=hour.optString("job_status");if(status.matches("failed|uncertain|cancelled")&&HourlyAutomation.enabled(this)){if(!hour.optString("job_error").isEmpty())c.addView(text(hour.optString("job_error"),12,MUTED));button(c,"重新生成这个小时",()->new LocalDialog(this).setTitle("重试这一小时").setMessage("使用当前原文重新请求分析服务，可能产生费用。上次中断的请求也可能已被服务接收。").setPositiveButton("重试",(d,w)->background(()->HourlySummaries.retry(store,hour.optString("id")),this::load)).setNegativeButton("取消",null).show());}
        JSONArray sources=evidence.getJSONArray("sources");if(sources.length()>0)button(c,"查看本小时原文",()->{try{String[] names=new String[sources.length()];for(int i=0;i<names.length;i++)names[i]=store.audio(sources.getJSONObject(i).getString("source_id")).optString("title");new LocalDialog(this).setTitle("本小时的录音").setItems(names,(d,n)->{try{JSONObject a=store.audio(sources.getJSONObject(n).getString("source_id"));startActivity(new Intent(this,RecordActivity.class).putExtra("id",a.getString("id")).putExtra("seek_ms",Math.max(0,hour.optLong("start")-a.optLong("created"))));}catch(Exception e){notice.setText("来源已删除");}}).show();}catch(Exception e){notice.setText("来源已更新，请稍后重试");}});
    }
    private void showClaim(LinearLayout parent,JSONObject claim)throws Exception {
        gap(parent,8);parent.addView(rawText((claim.optString("kind").equals("inference")?"待核对 · ":"• ")+claim.getString("text"),15,INK));JSONArray citations=claim.getJSONArray("citations");for(int i=0;i<citations.length();i++){JSONObject ref=citations.getJSONObject(i);String quote=ref.optString("quote");boolean playable=false;try{playable=SourceAnswer.playable(store.audio(ref.getString("source_id")),new JSONObject(ref.toString()).put("timed",true));}catch(Exception ignored){}TextView source=rawText("“"+quote+"”\n↗ "+TranscriptDocument.clock(ref.optLong("source_created")+ref.optLong("start_ms"))+(playable?" · 查看原文与回听":" · 查看原文，原音不可用"),12,SAGE);source.setMinHeight(dp(48));source.setPadding(dp(12),dp(10),dp(12),dp(10));source.setBackground(bg(TINT,12));parent.addView(source);source.setOnClickListener(v->{try{JSONObject current=store.audio(ref.getString("source_id"));if(current.optLong("transcript_revision")!=ref.optLong("source_revision")){notice.setText("原文已修改，正在等待新的小时总结");load();return;}startActivity(new Intent(this,RecordActivity.class).putExtra("id",ref.getString("source_id")).putExtra("seek_ms",ref.optLong("start_ms")));}catch(Exception e){notice.setText("来源已删除，请刷新总结");load();}});}
    }
    private final Runnable tick=new Runnable(){public void run(){load();refresh.postDelayed(this,5000);}};
    public void onResume(){super.onResume();refresh.removeCallbacks(tick);refresh.post(tick);}
    public void onPause(){refresh.removeCallbacks(tick);super.onPause();}
    public void onDestroy(){generation++;loader.shutdown();refresh.removeCallbacksAndMessages(null);super.onDestroy();}
    void onUnderstandingUpdated(){load();}
}
